mapper.select:
WITH boundaries AS (
    SELECT c.agent_id, MAX(c.sequence_num) AS sequence_num
    FROM code_session_internal_events c
    WHERE c.workspace_uuid = #{params.WorkspaceUUID}
      AND c.code_session_external_id = #{params.CodeSessionExternalID}
      AND (
          (#{params.Subagents} AND c.agent_id IS NOT NULL)
          OR (NOT #{params.Subagents} AND c.agent_id IS NULL)
      )
      AND c.is_compaction
      AND c.deleted_at IS NULL
    GROUP BY c.agent_id
)
SELECT

FROM code_session_internal_events e
LEFT JOIN boundaries b ON b.agent_id IS NOT DISTINCT FROM e.agent_id
WHERE e.workspace_uuid = #{params.WorkspaceUUID}
  AND e.code_session_external_id = #{params.CodeSessionExternalID}
  AND (
      (#{params.Subagents} AND e.agent_id IS NOT NULL)
      OR (NOT #{params.Subagents} AND e.agent_id IS NULL)
  )
  AND e.deleted_at IS NULL
  AND e.sequence_num > GREATEST(
      CAST(#{params.AfterSequence} AS bigint),
      COALESCE(b.sequence_num - 1, 0)
  )
ORDER BY e.sequence_num ASC
LIMIT #{params.Limit}
